parameters.jsCode:
// Outil « Lire une page » : lit une page web et renvoie son texte, les liens sous la forme « texte du lien [URL] ».
// Une lecture en échec renvoie un message court au lieu du contenu : « Page inaccessible (code) : non lue ».
const LONGUEUR_MAX = 15000;
const url = String((query && typeof query === 'object' ? query.url : query) ?? '').trim();
if (!/^https?:\/\//i.test(url)) return 'Page inaccessible (URL invalide) : non lue';

const entites = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', eacute: 'é', egrave: 'è', ecirc: 'ê', agrave: 'à', acirc: 'â', ccedil: 'ç', ugrave: 'ù', ucirc: 'û', ocirc: 'ô', icirc: 'î', iuml: 'ï', euml: 'ë', rsquo: '’', lsquo: '‘', laquo: '«', raquo: '»', hellip: '…', ndash: '–', mdash: '—', euro: '€', deg: '°', oelig: 'œ' };
const decoder = (s) => s
  .replace(/&#(\d+);/g, (m, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&([a-z]+);/gi, (m, nom) => entites[nom.toLowerCase()] ?? m);
const sansBalises = (s) => decoder(s.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

try {
  const aide = (typeof helpers !== 'undefined' && helpers) || this.helpers;
  const reponse = await aide.httpRequest({
    url,
    method: 'GET',
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; Loupe/1.0)', Accept: 'text/html,application/xhtml+xml' },
    timeout: 15000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    json: false,
  });
  const code = Number(reponse?.statusCode ?? 0);
  if (code >= 400) return 'Page inaccessible (' + code + ') : non lue';
  const type = String((reponse?.headers ?? {})['content-type'] ?? '').split(';')[0].trim().toLowerCase();
  if (type && !/^(text\/html|application\/xhtml\+xml|text\/plain)$/.test(type)) return 'Ce lien est un fichier (' + type + '), non lu';
  const html = reponse?.body;
  if (typeof html !== 'string' || !html.trim()) return 'Page inaccessible (réponse vide) : non lue';

  const titre = sansBalises((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) ?? [])[1] ?? '');
  if (/\b404\b|not found|introuvable|non trouvée|n['’]existe pas/i.test(titre)) return "Page inaccessible (page d'erreur) : non lue";

  let corps = html.replace(/<!--[\s\S]*?-->/g, ' ');
  corps = (corps.match(/<body[^>]*>([\s\S]*)<\/body>/i) ?? [])[1] ?? corps;
  corps = corps
    .replace(/<(script|style|noscript|svg|template|iframe|head)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<a\b[^>]*?\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>([\s\S]*?)<\/a>/gi, (m, a, b, c, contenu) => {
      const lien = decoder(String(a ?? b ?? c ?? '').trim());
      const texte = sansBalises(contenu);
      if (!lien || /^(javascript:|#)/i.test(lien)) return ' ' + texte + ' ';
      return texte ? ' ' + texte + ' [' + lien + '] ' : ' ';
    })
    .replace(/<\/?(p|div|li|ul|ol|h[1-6]|tr|section|article|header|footer|nav|br)\b[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  const texte = decoder(corps).replace(/[ \t ]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{2,}/g, '\n').trim();
  if (!texte) return 'Page inaccessible (page sans texte) : non lue';
  return ((titre ? 'Titre : ' + titre + '\n' : '') + texte).slice(0, LONGUEUR_MAX);
} catch (err) {
  const message = String(err?.message ?? err) + ' ' + String(err?.code ?? err?.cause?.code ?? '');
  const motif = /ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(message) ? 'adresse introuvable'
    : /ECONNABORTED|ETIMEDOUT|ESOCKETTIMEDOUT|timeout|timed out|aborted/i.test(message) ? 'délai dépassé'
    : 'erreur réseau';
  return 'Page inaccessible (' + motif + ') : non lue';
}

