parameters.jsCode:
// Classe l'échec de « Vérifier le site » : accès refusé (403/429), délai dépassé, DNS, autre.
const err = $input.first().json.error;
const o = err && typeof err === 'object' ? err : {};
const brut = typeof err === 'string' ? err : JSON.stringify(err ?? '');

const statut =
  Number(o.httpCode ?? o.statusCode ?? o.status ?? o.response?.status ?? o.cause?.status ?? o.cause?.response?.status) ||
  Number((brut.match(/status code (\d{3})/i) ?? [])[1]) ||
  null;
const code = String(o.code ?? o.cause?.code ?? o.errno ?? '');
const indices = code + ' ' + brut;

let categorie;
let message;
if (statut === 403) {
  categorie = 'site_acces_refuse';
  message = 'Analyse impossible : le site refuse les requêtes automatisées (HTTP 403).';
} else if (statut === 429) {
  categorie = 'site_acces_refuse';
  message = 'Analyse impossible : le site limite le nombre de requêtes (HTTP 429). Réessayez dans quelques minutes.';
} else if (statut) {
  categorie = 'site_autre';
  message = 'Analyse impossible : le site a répondu par une erreur (HTTP ' + statut + ').';
} else if (/ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(indices)) {
  categorie = 'site_dns';
  message = "Analyse impossible : adresse introuvable. Vérifiez l'URL saisie.";
} else if (/ECONNABORTED|ETIMEDOUT|ESOCKETTIMEDOUT|timeout|timed out/i.test(indices)) {
  categorie = 'site_timeout';
  message = "Analyse impossible : le site n'a pas répondu dans le délai de 15 secondes.";
} else {
  categorie = 'site_autre';
  message = 'Analyse impossible : le site est inaccessible.';
}

const detail = String(o.message ?? o.description ?? brut).slice(0, 500);

return [
  {
    json: {
      categorie,
      message_page: message,
      error: ('[' + categorie + '] ' + message + ' — détail : ' + detail).slice(0, 2000),
    },
  },
];

// Compare la sortie de l'agent au texte des pages réellement lues.
// Sortie : avertissements = liste d'objets { terme, champ } pour les termes réglementaires et les mots
// en majuscules (2 à 6 lettres) cités par l'agent mais absents des pages ; nb_pages = pages lues sans erreur.
const TERMES = [
  { terme: 'AFNOR', motif: 'AFNOR' },
  { terme: 'INRS', motif: 'INRS' },
  { terme: 'ISO', motif: 'ISO', motEntier: true },
  { terme: 'NF', motif: 'NF', motEntier: true },
  { terme: 'décret', motif: 'décrets?', insensible: true },
  { terme: 'arrêté', motif: 'arrêtés?', insensible: true },
  { terme: 'obligation légale', motif: 'obligations?\\s+légales?', insensible: true },
  { terme: 'autorités', motif: 'autorités', insensible: true },
  { terme: 'certification', motif: 'certifications?', insensible: true },
  { terme: 'homologation', motif: 'homologations?', insensible: true },
  { terme: 'agrément', motif: 'agréments?', insensible: true },
];
// Champs non contrôlés : résumé du contexte saisi, liste des pages et URL de source.
const CHAMPS_IGNORES = ['contexte_resume', 'pages_analysees', 'source', 'citation'];
// Sigles courants admis même s'ils ne figurent pas dans les pages : copie de loupe/config/sigles-autorises.json.
const SIGLES_AUTORISES = ["SMS", "CRM", "ERP", "API", "KPI", "ROI", "PDF", "HT", "TTC", "TVA", "SaaS", "B2B", "B2C", "UX", "UI", "IA", "SEO", "FAQ", "CSV", "JSON"].map((sigle) => sigle.toUpperCase());
// L'outil renvoie son texte dans une enveloppe JSON ([{"response":"…"}]) : on en extrait le texte.
const deballer = (observation) => {
  const brut = typeof observation === 'string' ? observation : JSON.stringify(observation ?? '');
  try {
    const valeur = JSON.parse(brut);
    const textes = (Array.isArray(valeur) ? valeur : [valeur]).map((x) => (x && typeof x === 'object' ? x.response ?? x.data : x)).filter((x) => typeof x === 'string');
    if (textes.length) return textes.join('\n');
  } catch (err) {
    // pas du JSON : texte brut
  }
  return brut;
};
const normaliser = (s) => String(s ?? '').normalize('NFC').replace(/[  ]/g, ' ');
const motEntier = (motif, options) => new RegExp('(?<![\\p{L}\\p{N}])(?:' + motif + ')(?![\\p{L}\\p{N}])', options);

try {
  const agent = $('Analyse brute').first().json;
  const etapes = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
  // Résultat de chaque appel de l'outil « Lire une page » : du JSON sous forme de texte.
  const observations = etapes.map((etape) => deballer(etape?.observation));
  // Lectures en échec : message court du nouvel outil, ou objet d'erreur de l'ancien.
  const enEchec = (o) => o.trim() === '' || /^\s*(Page inaccessible|Ce lien est un fichier|There was an error)/i.test(o) || /^\s*\[?\s*\{\s*\\*"error\\*"/.test(o);
  const nb_pages = observations.filter((o) => !enEchec(o)).length;

  // Texte des pages : résultats de l'outil et page d'accueil, sans scripts, balises ni séquences d'échappement.
  const accueil = String($('Vérifier le site').first().json.data ?? '')
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
  const pages = normaliser(observations.filter((o) => !enEchec(o)).join(' ').replace(/\\+[nrt]/g, ' ').replace(/\\+"/g, '"') + ' ' + accueil);
  // Les sigles saisis dans le contexte ne sont pas signalés.
  const pagesEtContexte = pages + ' ' + normaliser($('Créer analyse').first().json.contexte);

  const champs = [];
  const parcourir = (valeur, chemin) => {
    if (typeof valeur === 'string') champs.push({ chemin, texte: normaliser(valeur) });
    else if (Array.isArray(valeur)) valeur.forEach((v, i) => parcourir(v, chemin + '[' + i + ']'));
    else if (valeur && typeof valeur === 'object') {
      for (const [cle, v] of Object.entries(valeur)) {
        if (!CHAMPS_IGNORES.includes(cle)) parcourir(v, chemin ? chemin + '.' + cle : cle);
      }
    }
  };
  // Sortie contrôlée : l'analyse finale (pistes régénérées comprises), sinon celle de l'agent.
  let finale = {};
  try { finale = $('Analyse finale').first().json ?? {}; } catch (err) { finale = {}; }
  parcourir(finale.output ?? agent.output, '');

  // Les avertissements de la relecture critique sont repris en tête.
  const avertissements = Array.isArray(finale.avertissements_relecture) ? [...finale.avertissements_relecture] : [];
  // Avertissement éventuel de la rédaction (modèle de rédaction en échec).
  if (Array.isArray(agent.avertissements_redaction)) avertissements.push(...agent.avertissements_redaction);
  // 1. Termes réglementaires.
  for (const { terme, motif, insensible, motEntier: entier } of TERMES) {
    const options = insensible ? 'iu' : 'u';
    const dansSortie = motEntier(motif, options);
    // Dans les pages, recherche sans limite de mot (la conversion en texte colle parfois deux mots),
    // sauf pour les sigles courts, qui se retrouveraient à l'intérieur d'autres mots.
    if ((entier ? dansSortie : new RegExp(motif, options)).test(pages)) continue;
    for (const { chemin, texte } of champs) {
      if (dansSortie.test(texte)) avertissements.push({ terme, champ: chemin });
    }
  }
  // 2. Mots en majuscules de 2 à 6 lettres absents des pages (comparaison sans tenir compte de la casse).
  const dejaControles = TERMES.map((t) => t.terme);
  const presence = {};
  for (const { chemin, texte } of champs) {
    const mots = [...new Set(texte.match(/(?<![\p{L}\p{N}])\p{Lu}{2,6}(?![\p{L}\p{N}])/gu) ?? [])];
    for (const mot of mots) {
      if (dejaControles.includes(mot) || SIGLES_AUTORISES.includes(mot)) continue;
      if (presence[mot] === undefined) presence[mot] = motEntier(mot, 'iu').test(pagesEtContexte);
      if (!presence[mot]) avertissements.push({ terme: mot, champ: chemin });
    }
  }
  // 3. Citations de l'inventaire : chaque extrait doit figurer dans le texte de sa page source.
  // Comparaison sur les lettres et les chiffres seulement : sans casse, espaces, ponctuation ni URL entre crochets
  // (la conversion en texte colle parfois deux mots et remplace les puces).
  const compacter = (s) => normaliser(s).toLowerCase()
    .replace(/\[\s*(?:https?:\/\/|\/|#|mailto:|tel:)[^\]\s]*\s*\]/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, '');
  const adresse = (u) => String(u ?? '').trim().replace(/\/+$/, '');
  const textesParPage = etapes.map((etape, i) => ({
    url: adresse(etape?.action?.toolInput?.url ?? etape?.action?.toolInput?.query),
    texte: compacter(observations[i].replace(/\\+[nrt]/g, ' ').replace(/\\+"/g, '"')),
  }));
  const toutesLesPages = compacter(pages);
  const inventaire = (finale.output ?? agent.output)?.inventaire_existant;
  (Array.isArray(inventaire) ? inventaire : []).forEach((element, i) => {
    const citation = String(element?.citation ?? '');
    // Une citation abrégée par des points de suspension est vérifiée morceau par morceau.
    const morceaux = citation.split(/…|\.\.\./).map(compacter).filter((m) => m.length >= 4);
    const page = textesParPage.filter((p) => p.url === adresse(element?.source)).map((p) => p.texte).join(' ');
    const texte = page || toutesLesPages;
    if (!morceaux.length || !morceaux.every((m) => texte.includes(m))) {
      avertissements.push({ terme: 'citation introuvable dans sa page : « ' + citation.slice(0, 80) + ' »', champ: 'inventaire_existant[' + i + ']' });
    }
  });
