} catch (err) {
  return [{ json: { avertissements: null, nb_pages: null, erreur_verification: String(err?.message ?? err) } }];
}

// Calcule la durée du proof-of-work en additionnant les heures des étapes (le modèle ne la fournit plus).
// Si le total dépasse 8 h, le nœud suivant demande une correction au modèle.
const DUREE_MAX_HEURES = 8;
// Marqueurs de révision : le proof-of-work final doit se lire comme une spécification autonome,
// sans trace d'une version précédente, d'une réduction, d'un budget ou d'une durée cible.
const MARQUEURS = [
  { terme: 'remplace', motif: 'remplace(?:nt)?' },
  { terme: 'au lieu de', motif: "au\\s+lieu\\s+d(?:e|u|es|['’])" },
  { terme: 'pour tenir', motif: 'pour\\s+tenir' },
  { terme: 'budget', motif: 'budgets?' },
  { terme: 'version précédente', motif: 'versions?\\s+précédentes?' },
  { terme: 'initialement', motif: 'initialement' },
  { terme: 'huit heures', motif: 'huit\\s+heures' },
  { terme: '8 h', motif: '8\\s*(?:h|heures?)' },
];
const marqueursDeRevision = (pow) => {
  const trouves = [];
  const parcourir = (valeur, chemin) => {
    if (typeof valeur === 'string') {
      const texte = valeur.normalize('NFC').replace(/[  ]/g, ' ');
      for (const { terme, motif } of MARQUEURS) {
        if (new RegExp('(?<![\\p{L}\\p{N}])(?:' + motif + ')(?![\\p{L}\\p{N}])', 'iu').test(texte)) {
          trouves.push({ terme: 'marqueur de révision : « ' + terme + ' »', champ: 'proof_of_work.' + chemin });
        }
      }
    } else if (Array.isArray(valeur)) valeur.forEach((v, i) => parcourir(v, chemin + '[' + i + ']'));
    else if (valeur && typeof valeur === 'object') for (const [cle, v] of Object.entries(valeur)) parcourir(v, chemin ? chemin + '.' + cle : cle);
  };
  parcourir(pow ?? {}, '');
  return trouves;
};
let proof_of_work;
let avertissements = null;
let nb_pages = null;
try {
  proof_of_work = $('Proposition proof-of-work').first().json.output ?? {};
  const verification = $('Vérifier termes réglementaires').first().json ?? {};
  avertissements = Array.isArray(verification.avertissements) ? [...verification.avertissements] : null;
  nb_pages = verification.nb_pages ?? null;

  const heures = (Array.isArray(proof_of_work.etapes) ? proof_of_work.etapes : [])
    .map((etape) => Number(etape?.heures))
    .filter((h) => Number.isFinite(h) && h > 0);
  let duree_totale = null;
  if (heures.length) {
    duree_totale = Math.round(heures.reduce((somme, h) => somme + h, 0) * 10) / 10;
    proof_of_work = { ...proof_of_work, duree_calculee_heures: duree_totale };
  }
  // Une piste signalée par la relecture et conservée ne doit jamais être retenue pour le proof-of-work.
  const comparer = (s) => String(s ?? '').normalize('NFC').toLowerCase().replace(/\s+/g, ' ').trim();
  const exclues = $('Analyse finale').first().json.pistes_exclues_pow ?? [];
  if (exclues.some((titre) => comparer(titre) === comparer(proof_of_work.piste_retenue))) {
    avertissements = [...(avertissements ?? []), { terme: 'proof-of-work établi sur une piste signalée : ' + proof_of_work.piste_retenue, champ: 'proof_of_work.piste_retenue' }];
  }
  const depasse = duree_totale !== null && duree_totale > DUREE_MAX_HEURES;
  // Sans réduction à venir, ce proof-of-work est le résultat final : ses marqueurs de révision sont signalés ici.
  if (!depasse) {
    const marqueurs = marqueursDeRevision(proof_of_work);
    if (marqueurs.length) avertissements = [...(avertissements ?? []), ...marqueurs];
  }
  return [{ json: { proof_of_work, avertissements, nb_pages, tentatives_pow: 1, duree_totale, depasse } }];
} catch (err) {
  return [{ json: { proof_of_work, avertissements, nb_pages, tentatives_pow: 1, duree_totale: null, depasse: false, erreur_duree: String(err?.message ?? err) } }];
}

// Réduction du proof-of-work : seuls le périmètre, le hors-périmètre, les étapes et le critère de succès viennent
// de la réduction ; le titre, l'objectif, la valeur pour l'entreprise, la justification, la piste retenue et la
// stack sont recopiés du premier jet. Le résultat réduit est conservé même s'il dépasse encore 8 h, avec un
// avertissement. Si la réduction a échoué, le premier jet est conservé, avec le même avertissement.
const DUREE_MAX_HEURES = 8;
// Marqueurs de révision : le proof-of-work final doit se lire comme une spécification autonome,
// sans trace d'une version précédente, d'une réduction, d'un budget ou d'une durée cible.
const MARQUEURS = [
  { terme: 'remplace', motif: 'remplace(?:nt)?' },
  { terme: 'au lieu de', motif: "au\\s+lieu\\s+d(?:e|u|es|['’])" },
  { terme: 'pour tenir', motif: 'pour\\s+tenir' },
  { terme: 'budget', motif: 'budgets?' },
  { terme: 'version précédente', motif: 'versions?\\s+précédentes?' },
  { terme: 'initialement', motif: 'initialement' },
  { terme: 'huit heures', motif: 'huit\\s+heures' },
  { terme: '8 h', motif: '8\\s*(?:h|heures?)' },
];
const marqueursDeRevision = (pow) => {
  const trouves = [];
  const parcourir = (valeur, chemin) => {
    if (typeof valeur === 'string') {
      const texte = valeur.normalize('NFC').replace(/[  ]/g, ' ');
      for (const { terme, motif } of MARQUEURS) {
        if (new RegExp('(?<![\\p{L}\\p{N}])(?:' + motif + ')(?![\\p{L}\\p{N}])', 'iu').test(texte)) {
          trouves.push({ terme: 'marqueur de révision : « ' + terme + ' »', champ: 'proof_of_work.' + chemin });
        }
      }
    } else if (Array.isArray(valeur)) valeur.forEach((v, i) => parcourir(v, chemin + '[' + i + ']'));
    else if (valeur && typeof valeur === 'object') for (const [cle, v] of Object.entries(valeur)) parcourir(v, chemin ? chemin + '.' + cle : cle);
  };
  parcourir(pow ?? {}, '');
  return trouves;
};
const avertir = (liste, total, suffixe) => [...(liste ?? []), { terme: 'durée totale de ' + String(total).replace('.', ',') + ' h' + suffixe + ' (plus de ' + DUREE_MAX_HEURES + ' h)', champ: 'proof_of_work.etapes' }];
const premier = $('Calculer durée').first().json;
let resultat = {
  proof_of_work: premier.proof_of_work,
  avertissements: avertir(premier.avertissements, premier.duree_totale, ''),
  nb_pages: premier.nb_pages ?? null,
  tentatives_pow: 2,
};
try {
  const corrige = $('Corriger proof-of-work').first().json.output;
  const heures = (Array.isArray(corrige?.etapes) ? corrige.etapes : [])
    .map((etape) => Number(etape?.heures))
    .filter((h) => Number.isFinite(h) && h > 0);
  if (heures.length) {
    const total = Math.round(heures.reduce((somme, h) => somme + h, 0) * 10) / 10;
    const jet = premier.proof_of_work ?? {};
    resultat.proof_of_work = {
      ...jet,
      perimetre: Array.isArray(corrige.perimetre) && corrige.perimetre.length ? corrige.perimetre : jet.perimetre,
      hors_perimetre: Array.isArray(corrige.hors_perimetre) && corrige.hors_perimetre.length ? corrige.hors_perimetre : jet.hors_perimetre,
      etapes: corrige.etapes,
      critere_de_succes: typeof corrige.critere_de_succes === 'string' && corrige.critere_de_succes.trim() ? corrige.critere_de_succes : jet.critere_de_succes,
      duree_calculee_heures: total,
    };
    resultat.avertissements = total > DUREE_MAX_HEURES ? avertir(premier.avertissements, total, ' après correction') : premier.avertissements ?? null;
  }
} catch (err) {
  resultat.erreur_duree = String(err?.message ?? err);
}
// Marqueurs de révision du proof-of-work final.
const marqueurs = marqueursDeRevision(resultat.proof_of_work);
if (marqueurs.length) resultat.avertissements = [...(resultat.avertissements ?? []), ...marqueurs];
return [{ json: resultat }];

