// Analyse finale : analyse rédigée, où les pistes signalées par la relecture (doublon de l'existant ou effort
// ajouté à l'utilisateur) sont remplacées
// par leur version régénérée. Une piste en doublon qui n'a pas pu être régénérée est conservée,
// avec un avertissement. En cas d'erreur, la sortie de l'agent est reprise telle quelle.
const comparer = (s) => String(s ?? '').normalize('NFC').toLowerCase().replace(/\s+/g, ' ').trim();
let output = $('Analyse brute').first().json.output ?? {};
const avertissements_relecture = [];
const pistes_signalees = [];
let output_pow;
let pistes_exclues_pow = [];
let erreur_relecture;
try {
  const relecture = $('Relecture critique').first().json.output;
  const doublons = (Array.isArray(relecture?.pistes) ? relecture.pistes : []).filter((piste) => piste?.duplique === true || piste?.ajoute_effort === true);
  if (doublons.length) {
    let nouvelles = [];
    if ($('Régénérer pistes').isExecuted) {
      const regeneration = $('Régénérer pistes').first().json.output;
      nouvelles = Array.isArray(regeneration?.pistes) ? regeneration.pistes : [];
    }
    const pistes = [...(Array.isArray(output.pistes) ? output.pistes : [])];
    doublons.forEach((doublon, rang) => {
      const index = pistes.findIndex((piste) => comparer(piste?.titre) === comparer(doublon.titre));
      // Correspondance par le titre remplacé, sinon par le rang quand les deux listes ont la même longueur.
      const nouvelle = nouvelles.find((n) => comparer(n?.remplace) === comparer(doublon.titre)) ?? (nouvelles.length === doublons.length ? nouvelles[rang] : undefined);
      const motif = doublon.duplique === true ? 'doublon' : 'effort';
      const signalement = { titre: doublon.titre, motif, element_existant: doublon.element_existant ?? '', effort_ajoute: doublon.effort_ajoute ?? '' };
      if (index >= 0 && nouvelle?.titre && nouvelle?.proposition) {
        const { remplace, ...piste } = nouvelle;
        pistes[index] = piste;
        pistes_signalees.push({ ...signalement, action: 'régénérée', nouveau_titre: piste.titre });
      } else {
        avertissements_relecture.push({ terme: (motif === 'doublon' ? "piste proche de l'existant : " : "piste qui ajoute un effort à l'utilisateur : ") + doublon.titre, champ: index >= 0 ? 'pistes[' + index + ']' : 'pistes' });
        pistes_signalees.push({ ...signalement, action: 'conservée' });
      }
    });
    output = { ...output, pistes };
    // Une piste signalée et conservée ne peut pas être retenue pour le proof-of-work :
    // elle est retirée de l'analyse transmise au modèle, sauf s'il ne resterait aucune piste.
    pistes_exclues_pow = pistes_signalees.filter((s) => s.action === 'conservée').map((s) => s.titre);
    const eligibles = pistes.filter((piste) => !pistes_exclues_pow.some((titre) => comparer(titre) === comparer(piste?.titre)));
    if (pistes_exclues_pow.length && eligibles.length) output_pow = { ...output, pistes: eligibles };
    else if (pistes_exclues_pow.length) avertissements_relecture.push({ terme: 'toutes les pistes sont signalées par la relecture : proof-of-work établi sur une piste signalée', champ: 'pistes' });
  }
} catch (err) {
  erreur_relecture = String(err?.message ?? err);
}
return [{ json: { output, output_pow: output_pow ?? output, pistes_exclues_pow, avertissements_relecture, pistes_signalees, erreur_relecture } }];

// Liste blanche des modèles : copie de loupe/config/modeles.json, à reporter ici à chaque modification du fichier.
// Le modèle de rédaction vient du champ caché « modele » du formulaire, sinon de la configuration.
// Tout modèle absent de la liste, ou au-delà du tarif d'entrée maximal, fait passer l'analyse en erreur.
const CONFIG = {
  "devise": "USD",
  "source_tarifs": "https://developers.openai.com/api/docs/pricing",
  "date_tarifs": "2026-10-12",
  "prix_max_entree_par_million": 3,
  "seuil_avertissement_cout": 0.3,
  "modele_exploration": "gpt-5-mini",
  "modele_redaction": "gpt-6.1-sol",
  "modeles": {
    "gpt-5-mini": {
      "entree": 0.25,
      "entree_cache": 0.025,
      "sortie": 2.0
    },
    "gpt-6.1-sol": {
      "entree": 2.0,
      "entree_cache": 0.1,
      "sortie": 10.0
    },
    "gpt-5.6-terra": {
      "entree": 2.0,
      "entree_cache": 0.2,
      "sortie": 12.0
    }
  }
};

const MESSAGE = 'Analyse impossible : modèle non autorisé.';
let modele_exploration;
let modele_redaction;
try {
  modele_exploration = String(CONFIG.modele_exploration ?? '');
  const demande = String($('Formulaire').first().json.modele ?? '').trim();
  modele_redaction = demande || String(CONFIG.modele_redaction ?? '');
  const refus = (modele) => {
    if (!modele || !Object.prototype.hasOwnProperty.call(CONFIG.modeles, modele)) return 'modèle non autorisé : ' + (modele || '(vide)');
    const entree = Number(CONFIG.modeles[modele]?.entree);
    if (!(entree <= Number(CONFIG.prix_max_entree_par_million))) return "modèle non autorisé (tarif d'entrée au-delà du plafond) : " + modele;
    return null;
  };
  const erreur = refus(modele_exploration) ?? refus(modele_redaction);
  if (erreur) return [{ json: { autorise: false, modele_exploration, modele_redaction, error: erreur, message_page: MESSAGE } }];
  return [{ json: { autorise: true, modele_exploration, modele_redaction } }];
} catch (err) {
  return [{ json: { autorise: false, modele_exploration, modele_redaction, error: 'modèle non autorisé (configuration illisible) : ' + String(err?.message ?? err), message_page: MESSAGE } }];
}

// Texte des pages lues par l'agent d'exploration, chaque page précédée de son URL :
// c'est ce que reçoivent le modèle de rédaction et la relecture critique.
// Les lectures en échec (« Page inaccessible… », « Ce lien est un fichier… ») sont écartées et listées à part.
const ECHEC = /^\s*(Page inaccessible|Ce lien est un fichier|There was an error)/i;
// L'outil renvoie son texte dans une enveloppe JSON ([{"response":"…"}]) : on en extrait le texte.
const deballer = (observation) => {
  const brut = typeof observation === 'string' ? observation : JSON.stringify(observation ?? '');
  try {
    const valeur = JSON.parse(brut);
    const textes = (Array.isArray(valeur) ? valeur : [valeur]).map((x) => (x && typeof x === 'object' ? x.response ?? x.data : x)).filter((x) => typeof x === 'string');
    if (textes.length) return textes.join('\n');
  } catch (err) {
    // pas du JSON : texte brut
  }
  return brut;
};
const etapes = $('Agent exploration').first().json.intermediateSteps;
const pages = [];
const pages_en_echec = [];
for (const etape of Array.isArray(etapes) ? etapes : []) {
  const entree = etape?.action?.toolInput;
  const url = String((entree && typeof entree === 'object' ? entree.url ?? entree.query : entree) ?? 'page');
  const observation = deballer(etape?.observation);
  if (observation.trim() === '' || ECHEC.test(observation)) pages_en_echec.push({ url, message: observation.trim().slice(0, 120) });
  else pages.push({ url, texte: observation.slice(0, 15000) });
}
if (!pages.length) throw new Error("aucune page n'a pu être lue");
return [{ json: { texte_pages: pages.map((page) => '### ' + page.url + '\n' + page.texte).join('\n\n'), pages_lues: pages.map((page) => page.url), nb_pages: pages.length, pages_en_echec } }];

