// Analyse brute : l'analyse du modèle de rédaction, complétée par l'inventaire et les pages de l'agent d'exploration.
// Les étapes de l'agent (pages lues) sont transmises telles quelles aux nœuds suivants.
const exploration = $('Agent exploration').first().json;
const redaction = $('Rédiger analyse').first().json.output;
if (!redaction || !Array.isArray(redaction.pistes) || !redaction.pistes.length) throw new Error("rédaction de l'analyse incomplète");

const adresse = (u) => String(u ?? '').trim().replace(/\/+$/, '');
const lues = ($('Texte des pages').first().json.pages_lues ?? []).map(adresse);
// Pages analysées : celles que l'agent déclare et qui ont réellement été lues ; à défaut, les pages lues.
let pages_analysees = (Array.isArray(exploration.output?.pages_analysees) ? exploration.output.pages_analysees : [])
  .filter((page) => page && lues.includes(adresse(page.url)));
if (!pages_analysees.length) pages_analysees = lues.map((url) => ({ url, titre: url.split('/').filter(Boolean).pop() ?? url }));

const { pistes, perimetre_non_couvert, contexte_resume, ...debut } = redaction;
const output = {
  ...debut,
  inventaire_existant: Array.isArray(exploration.output?.inventaire_existant) ? exploration.output.inventaire_existant : [],
  pistes,
  perimetre_non_couvert: perimetre_non_couvert ?? [],
  contexte_resume: contexte_resume ?? '',
  pages_analysees,
};
return [{ json: { output, intermediateSteps: exploration.intermediateSteps ?? [], redige_par: $('Configuration modèles').first().json.modele_redaction, avertissements_redaction: [] } }];

